function Buggy() {
  throw new Error('I crashed during render!');
}

function App() {
  const [show, setShow] = useState(false);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setShow(true)}>Render buggy child</button>
      <ErrorBoundary>
        {show ? <Buggy /> : <p>All good so far.</p>}
      </ErrorBoundary>
    </div>
  );
}

class ErrorBoundary extends React.Component {
  state = { error: null };
  static getDerivedStateFromError(error) {
    return { error };
  }
  reset = () => this.setState({ error: null });
  render() {
    if (this.state.error) {
      return (
        <div style={{ border: '1px solid crimson', padding: 12, borderRadius: 8 }}>
          <p style={{ color: 'crimson' }}>Error: {this.state.error.message}</p>
          <button onClick={this.reset}>Try again</button>
        </div>
      );
    }
    return this.props.children;
  }
}

