class ErrorBoundary extends React.Component {
  state = { hasError: false };
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  render() {
    if (this.state.hasError) return <p>Something went wrong.</p>;
    return this.props.children;
  }
}

function Widget() {
  const [error, setError] = useState(null);
  const handleClick = () => {
    try {
      throw new Error('clicked and failed');
    } catch (e) {
      setError(e.message); // surface async/handler errors via state yourself
    }
  };
  return (
    <div>
      <button onClick={handleClick}>Do the thing</button>
      {error && <p style={{ color: 'crimson' }}>Error: {error}</p>}
    </div>
  );
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <ErrorBoundary>
        <Widget />
      </ErrorBoundary>
    </div>
  );
}

class ErrorBoundary extends React.Component {
  state = { error: null };
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    // In production: Sentry.captureException(error, { extra: info });
    console.error('Reported:', error, info.componentStack);
  }
  render() {
    if (this.state.error) {
      const { fallback } = this.props;
      return typeof fallback === 'function'
        ? fallback(this.state.error)
        : fallback;
    }
    return this.props.children;
  }
}

function App() {
  return (
    <ErrorBoundary fallback={(err) => <p>Failed: {err.message}</p>}>
      <MyWidget />
    </ErrorBoundary>
  );
}
